struct singleton_vtable {
  char pad[8];
  short adjustment;
  short reserved;
  void (*destroy)(void *, int);
};

#define DECLARE_SINGLETON(type, symbol) \
class type { \
public: \
  singleton_vtable *vtable; \
  static type *instance; \
  static void delete_inst() { \
    if (instance != 0) { \
      delete instance; \
      instance = 0; \
    } \
  } \
}; \
type *type::instance __asm__(symbol)

