struct entity_manager {
  char pad[12];
  singleton_vtable *vtable;
  static entity_manager *instance;
  static void delete_inst() {
    if (instance != 0) {
      entity_manager *object = instance;
      singleton_vtable *table = object->vtable;
      table->destroy((char *)object + 12 + table->adjustment, 3);
      instance = 0;
    }
  }
};
entity_manager *entity_manager::instance
  __asm__("_14entity_manager$instance");

extern "C" void arch_free(void *) __asm__("arch_free__FPv");
extern void *particle_allocator_freelist[];
__asm__(".equ particle_allocator_freelist, 0x003E5628");

class particle_generator;
class particle_cleaner {
public:
  particle_generator **start;
  particle_generator **finish;
  particle_generator **end;

  ~particle_cleaner() {
    unsigned int count = finish - start;
    if (count != 0) {
      unsigned int bytes = count * sizeof(particle_generator *);
      if (bytes > 128)
        arch_free(start);
      else {
        unsigned int index = (count >> 3) - 1;
        *start = (particle_generator *)particle_allocator_freelist[index];
        particle_allocator_freelist[index] = start;
      }
    }
  }
};

extern particle_cleaner *g_particle_cleaner;
__asm__(".equ g_particle_cleaner, 0x0043AB98");

